mapper.select:
SELECT ph.id, ph.user_id, ph.category_id, ph.prompt_type, ph.prompt_text, ph.image_url, ph.init_regi_pic, ph.init_regi_dttm, ph.final_rvis_pic, ph.final_rvis_dttm FROM prompt_history ph
JOIN "user" u ON ph.user_id = u.id WHERE u.team_name = #{teamName}
ORDER BY ph.init_regi_dttm DESC
